import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class CounterTest {
    @Test void countsStrictlyPositiveValuesWithoutMutation() {
        int[] input = {-3, 0, 4, 4};
        assertEquals(2, Counter.positive(input));
        assertArrayEquals(new int[] {-3, 0, 4, 4}, input);
    }
    @Test void emptyAndZeroHaveNoPositiveValues() {
        assertEquals(0, Counter.positive(new int[] {}));
        assertEquals(0, Counter.positive(new int[] {0}));
    }
    @Test void rejectsNullAccordingToTheContract() {
        assertThrows(IllegalArgumentException.class,
                () -> Counter.positive(null));
    }
}
